mapper.select:
SELECT event_content_id, mapx, mapy, display_yn
FROM event
WHERE event_content_id = #{eventContentId}

SELECT * FROM ( SELECT p.content_id, p.place_name, p.addr, p.mapx, p.mapy, p.image_url, p.cuisine_type, p.open_time, p.close_time, p.break_open_time, p.break_close_time, 6371000 * 2 * ASIN(SQRT( POW(SIN(RADIANS(p.mapy - #{lat}) / 2), 2) + COS(RADIANS(#{lat})) * COS(RADIANS(p.mapy)) * POW(SIN(RADIANS(p.mapx - #{lng}) / 2), 2) )) AS distance FROM place p WHERE p.display_yn = TRUE AND p.content_type_cd = 39 AND p.mapy BETWEEN #{minLat} AND #{maxLat} AND p.mapx BETWEEN #{minLng} AND #{maxLng}
AND ( (#{cuisineType} = 'ALL' AND p.cuisine_type IN ('KOREAN', 'WESTERN', 'JAPANESE', 'CHINESE')) OR (#{cuisineType} != 'ALL' AND p.cuisine_type = #{cuisineType}) )
AND p.open_time IS NOT NULL AND p.close_time IS NOT NULL AND ( (p.close_time > p.open_time AND #{mealTime} >= p.open_time AND #{mealTime} < p.close_time) OR (p.close_time < p.open_time AND (#{mealTime} >= p.open_time OR #{mealTime} < p.close_time)) ) AND ( p.break_open_time IS NULL OR p.break_close_time IS NULL OR NOT (#{mealTime} >= p.break_open_time AND #{mealTime} < p.break_close_time) )
) near WHERE near.distance <= #{radius} ORDER BY near.distance, near.content_id LIMIT #{limit} OFFSET #{offset}
